  static Package Make(string folder,string version,string[] targets,string[] values,string id="unturned.ai.tchinese"){var files=new List<PackageFile>();for(int i=0;i<targets.Length;i++){Put(folder,"payload/"+targets[i],values[i]);files.Add(new PackageFile{source="payload/"+targets[i],target=targets[i],sha256=Data.Hash(Paths.Safe(folder,"payload/"+targets[i]))});}Data.Write(Path.Combine(folder,Packages.ManifestName),new PackageManifest{schemaVersion=1,id=id,name="Reconcile fixture",version=version,kind=id=="test.beta"?"module":"localization",packageIdentity=id=="test.beta"?null:"unturned.ai.tchinese",files=files});return Packages.Load(folder,"fixture");}
