  public static int Run(string output){using(var deadline=new TestDeadline(90000)){results=new List<string>();string root=Path.Combine(Path.GetFullPath(output),"reconcile-"+Guid.NewGuid().ToString("N")),game=Path.Combine(root,"game"),state=Path.Combine(root,"manager"),assistant=Path.Combine(root,"assistant"),sources=Path.Combine(root,"sources");Directory.CreateDirectory(game);File.WriteAllText(Path.Combine(game,"Unturned.exe"),"fixture");string a="Localization/Tchinese/Editor/A.dat",b="Maps/PEI/Tchinese.dat",c="Bundles/Old/C/Tchinese.dat",d="Bundles/Old/D/Tchinese.dat";foreach(string target in new[]{a,b,c,d})Put(game,target,"before manager "+target);var old=Make(Path.Combine(sources,"old"),"1.0.0",new[]{a,b,c,d},new[]{"oldA","oldB","oldC","oldD"});var next=Make(Path.Combine(sources,"new"),"2.0.0",new[]{a,b},new[]{"newA","newB"});var engine=new Engine(game,state,true);engine.Install(old,engine.Collisions(old));string registryFile=Path.Combine(engine.State,"installed.json"),beforeRegistry=File.ReadAllText(registryFile);var oldOriginal=engine.ReadRegistry().packages.Single().files.First(f=>f.target==a);string managerBackup=Paths.Safe(engine.State,"original/"+Data.Key(a)+".bak"),managerBackupHash=Data.Hash(managerBackup);Put(game,a,"newA");Put(game,b,"newB");Put(game,d,"manual extra");Put(assistant,"operation.lock","");var legacy=new AssistantRecord{product="Unturned.AI.Tchinese",gameRoot=game,version="2.0.0",files=new List<AssistantOwned>()};foreach(string target in new[]{a,b}){Put(assistant,"original/"+target,"assistant original "+target);legacy.files.Add(new AssistantOwned{relative=target,hash=Data.Hash(Paths.Safe(game,target)),hadOriginal=true,originalHash=Data.Hash(Paths.Safe(assistant,"original/"+target))});}Data.Write(Path.Combine(assistant,"installed.json"),legacy);string legacyText=File.ReadAllText(Path.Combine(assistant,"installed.json"));
   var plan=engine.ReviewReconciliation(next,assistant);Check(plan.Files==2&&plan.Originals==2&&plan.Retained==2&&plan.RetainedDifferences==1&&plan.BackupDifferences==2,"review distinguishes verified files, extra old scope and differing restore points");Check(File.ReadAllText(registryFile)==beforeRegistry&&File.ReadAllText(Paths.Safe(game,d))=="manual extra","review changes neither records nor game files");
   Put(game,a,"unknown change");Reject(()=>engine.ReviewReconciliation(next,assistant),"unrecognized current translation blocks continuation");Put(game,a,"newA");Put(assistant,"original/"+a,"corrupt");Reject(()=>engine.ReviewReconciliation(next,assistant),"corrupt assistant backup blocks continuation");Put(assistant,"original/"+a,"assistant original "+a);
   File.WriteAllText(Path.Combine(assistant,"installed.json"),legacyText+" ");Reject(()=>engine.Reconcile(plan),"record changes after review block commit");File.WriteAllText(Path.Combine(assistant,"installed.json"),legacyText);Put(assistant,"transaction.json","{}");Reject(()=>engine.ReviewReconciliation(next,assistant),"unfinished assistant transaction blocks continuation");File.Delete(Path.Combine(assistant,"transaction.json"));legacy.product="other";Data.Write(Path.Combine(assistant,"installed.json"),legacy);Reject(()=>engine.ReviewReconciliation(next,assistant),"wrong assistant product is rejected");File.WriteAllText(Path.Combine(assistant,"installed.json"),legacyText);
   using(var locked=new FileStream(Path.Combine(assistant,"operation.lock"),FileMode.Open,FileAccess.ReadWrite,FileShare.None))Reject(()=>engine.ReviewReconciliation(next,assistant),"running assistant prevents concurrent continuation");Put(engine.State,"pending.json","{}");Reject(()=>engine.ReviewReconciliation(next,assistant),"unfinished manager transaction blocks continuation");File.Delete(Path.Combine(engine.State,"pending.json"));
   legacy.gameRoot=game+"-other";Data.Write(Path.Combine(assistant,"installed.json"),legacy);Reject(()=>engine.ReviewReconciliation(next,assistant),"a different target root is rejected");File.WriteAllText(Path.Combine(assistant,"installed.json"),legacyText);legacy.gameRoot=game;
   Put(game,a,"changed after review");Reject(()=>engine.Reconcile(plan),"current files are reverified at commit after confirmation");Check(File.ReadAllText(registryFile)==beforeRegistry,"failed continuation leaves the manager registry unchanged");Put(game,a,"newA");
   L.Language="zh-TW";string stored=L.Get("LegacyOwnedMismatch")+a;L.Language="zh-CN";Check(L.ManagerMessage(stored)==L.Get("Text163")+a,"legacy diagnostics use current language and avoid attributing an unverified cause");L.Language="zh-TW";
   var beforeTargets=new[]{a,b,c,d}.ToDictionary(t=>t,t=>Data.Hash(Paths.Safe(game,t)));var times=new[]{a,b,c,d}.ToDictionary(t=>t,t=>File.GetLastWriteTimeUtc(Paths.Safe(game,t)));plan=engine.ReviewReconciliation(next,assistant);string history=engine.Reconcile(plan);var registered=engine.ReadRegistry();var adopted=registered.packages.Single(p=>p.id==next.Manifest.id);var retained=registered.packages.Single(p=>p.retained);Check(adopted.version=="2.0.0"&&adopted.files.Count==2&&retained.files.Count==2,"continuation updates active version and preserves extra old records separately");Check(beforeTargets.All(p=>Data.Hash(Paths.Safe(game,p.Key))==p.Value&&File.GetLastWriteTimeUtc(Paths.Safe(game,p.Key))==times[p.Key]),"continuation writes no game content or timestamps");Check(Data.Hash(managerBackup)==managerBackupHash&&File.ReadAllText(Path.Combine(history,"manager-before.json"))==beforeRegistry,"old manager backups and exact record snapshot are retained");Check(File.ReadAllText(Path.Combine(assistant,"installed.json"))==legacyText&&Data.Hash(Paths.Safe(assistant,"original/"+a))==legacy.files[0].originalHash,"assistant records and backups remain unchanged");Check(adopted.files.All(f=>!string.IsNullOrEmpty(f.backupReference)),"adopted restore points use separate verified backup references");Check(engine.ReviewReconciliation(next,assistant).AlreadyCurrent,"repeated review detects an already aligned installation");Check(engine.Reconcile(engine.ReviewReconciliation(next,assistant))==null,"already aligned continuation is idempotent");engine.Install(next,null);Check(engine.LastWrittenFiles==0&&engine.ReadRegistry().packages.Single(p=>p.id==next.Manifest.id).files.All(f=>f.backupReference!=null),"later normal installation preserves imported restore references");var third=Make(Path.Combine(sources,"third"),"3.0.0",new[]{a,b},new[]{"thirdA","newB"});string alignedRegistry=File.ReadAllText(registryFile);engine.FailAfter=0;Reject(()=>engine.Install(third,null),"failed update after 